import type { RefObject } from "react";
import { Store } from "@tanstack/store";
import type {
  Conversation,
  ConversationEvent,
  ConversationEventAction,
  Flow,
  Stack,
  UnionEventType,
  VoiceErrorHandler,
} from "../types";
import { InspectorView } from "../types/inspector";

export type InspectorStoreState = {
  // Connection / tracker data
  sessionId: string;
  conversationList: Conversation[];
  stack: Stack[];
  inputDisabled: boolean;
  replayingConversation: boolean;
  waitingForUserInput: boolean;
  slots: Record<string, unknown>;
  slotRelatedEvents: ConversationEvent[];

  // UI state
  inspectMode: boolean;
  inspectorView: InspectorView;
  selectedElement: UnionEventType | undefined;

  // Flows data
  flows: Flow[];
  flowsLoading: boolean;
  flowsError: Error | null;

  // Configuration
  projectUrl: string;
  botDataEndpoint: string;
  trackerEndpoint: string;
  conversationEventActions: ConversationEventAction[];
  voiceFeaturesEnabled: boolean;
  isEmbedded: boolean;
  assistantId: string | null;
  authToken?: string;

  // Actions (populated by useBotConnection after socket setup)
  sendMessage: (message: string) => void;
  startNewConversation: () => void;
  replayConversation: (events: UnionEventType[]) => void;
  startVoiceStreaming: () => Promise<void>;
  stopVoiceStreaming: () => Promise<void>;
  onVoiceErrorRef: RefObject<VoiceErrorHandler>;
};

export type InspectorStore = Store<InspectorStoreState>;

// eslint-disable-next-line @typescript-eslint/no-empty-function
const noop = () => {};
const asyncNoop = () => Promise.resolve();

function createDefaultState(initialState?: Partial<InspectorStoreState>): InspectorStoreState {
  return {
    sessionId: "",
    conversationList: [],
    stack: [],
    inputDisabled: true,
    replayingConversation: false,
    waitingForUserInput: false,
    slots: {},
    slotRelatedEvents: [],

    inspectMode: false,
    inspectorView: InspectorView.ActiveFlow,
    selectedElement: undefined,

    flows: [],
    flowsLoading: false,
    flowsError: null,

    projectUrl: "",
    botDataEndpoint: "",
    trackerEndpoint: "",
    conversationEventActions: [],
    voiceFeaturesEnabled: true,
    isEmbedded: false,
    assistantId: null,
    authToken: undefined,

    sendMessage: noop,
    startNewConversation: noop,
    replayConversation: noop,
    startVoiceStreaming: asyncNoop,
    stopVoiceStreaming: asyncNoop,
    onVoiceErrorRef: { current: null },

    ...initialState,
  };
}

export function createInspectorStore(initialState?: Partial<InspectorStoreState>): InspectorStore {
  return new Store<InspectorStoreState>(createDefaultState(initialState));
}

export const inspectorStore: InspectorStore = createInspectorStore();

export function initInspectorStore(initialState?: Partial<InspectorStoreState>): InspectorStore {
  // Reset state on the existing singleton rather than replacing it, so all
  // components that already subscribed (e.g. StandaloneHeader, rendered before
  // InspectorContent in the same tree) keep their subscriptions and immediately
  // see subsequent updates such as assistantId being set by useConversationData.
  inspectorStore.setState(() => createDefaultState(initialState));
  return inspectorStore;
}
